import express from 'express';

const DASHBOARD_FUNCTION = Buffer.from('', 'base64').toString('utf8');
const originalGet = express.application.get;

function patchDashboardScript(source) {
  if (typeof source !== 'string') return source;
  const start = source.indexOf('function renderDashboard() {');
  if (start < 0) return source;
  const end = source.indexOf('\nfunction renderDisbursedLoans', start);
  if (end < 0) return source;
  return source.slice(0, start) + DASHBOARD_FUNCTION + source.slice(end);
}

if (!express.application.__jkClassicDashboardPatched) {
  Object.defineProperty(express.application, '__jkClassicDashboardPatched', { value: true, configurable: false });
  express.application.get = function patchedGet(path, ...handlers) {
    if (path !== '/app.js' || handlers.length === 0) {
      return originalGet.call(this, path, ...handlers);
    }

    const wrapped = handlers.map((handler) => {
      if (typeof handler !== 'function') return handler;
      return function jkDashboardRouteWrapper(req, res, next) {
        const originalSend = res.send.bind(res);
        res.send = function jkDashboardSend(body) {
          return originalSend(patchDashboardScript(body));
        };
        return handler(req, res, next);
      };
    });

    return originalGet.call(this, path, ...wrapped);
  };
}
